package app.studyforge.mobile;
import org.json.*;
import java.util.*;

/** Pure version ledger. Host configuration undo never overwrites a later manual change. */
final class FeatureVersions {
    static JSONObject apply(JSONObject workspace,JSONObject draft) throws Exception {
        JSONObject next=Json.copy(workspace),p=FeatureProgram.validate(draft.getJSONObject("program"));String id=draft.getString("id");JSONArray list=next.optJSONArray("features");if(list==null){list=new JSONArray();next.put("features",list);}JSONObject current=find(list,id),history=current==null?new JSONObject():Json.copy(current);JSONArray revisions=current==null?new JSONArray():Json.copy(current).optJSONArray("revisions");if(revisions==null)revisions=new JSONArray();history.remove("revisions");if(current!=null)revisions.put(history);while(revisions.length()>10)revisions.remove(0);
        JSONObject undo=new JSONObject(),expected=new JSONObject();applyPatch(next,p.getJSONObject("hostPatch"),undo,expected);JSONObject feature=Json.object("id",id,"revision",current==null?1:current.optInt("revision",1)+1,"program",p,"hash",FeatureProgram.hash(p),"revisions",revisions,"undoConfig",undo,"appliedConfig",expected,"request",draft.optString("request"),"checks",draft.optJSONObject("checks"),"enabled",true);
        if(current==null)list.put(feature);else for(int i=0;i<list.length();i++)if(id.equals(list.getJSONObject(i).optString("id")))list.put(i,feature);
        next.remove("featureDraft");return next;
    }
    static JSONObject undo(JSONObject workspace,String id) throws Exception {JSONObject next=Json.copy(workspace),f=find(next.optJSONArray("features"),id);if(f==null)throw new Exception("기능을 찾지 못했습니다.");JSONObject undo=f.optJSONObject("undoConfig"),expected=f.optJSONObject("appliedConfig");if(undo!=null)for(Iterator<String> it=undo.keys();it.hasNext();){String key=it.next();if(Objects.equals(String.valueOf(value(next,key)),String.valueOf(expected.opt(key))))set(next,key,undo.get(key));}JSONArray revisions=f.optJSONArray("revisions");if(revisions==null||revisions.length()==0){f.put("enabled",false);f.remove("undoConfig");f.remove("appliedConfig");}else{JSONObject prev=Json.copy(revisions.getJSONObject(revisions.length()-1));revisions.remove(revisions.length()-1);prev.put("revisions",revisions);JSONArray list=next.getJSONArray("features");for(int i=0;i<list.length();i++)if(id.equals(list.getJSONObject(i).optString("id")))list.put(i,prev);}return next;}
    static JSONObject find(JSONArray list,String id) throws Exception {if(list!=null)for(int i=0;i<list.length();i++)if(id.equals(list.getJSONObject(i).optString("id")))return list.getJSONObject(i);return null;}
    static Object value(JSONObject w,String key) throws Exception {return key.startsWith("settings.")?w.getJSONObject("settings").opt(key.substring(9)):w.opt(key);}
    static void set(JSONObject w,String key,Object v) throws Exception {JSONObject o=key.startsWith("settings.")?w.getJSONObject("settings"):w;String k=key.startsWith("settings.")?key.substring(9):key;if(v==null||v==JSONObject.NULL)o.remove(k);else o.put(k,v);}
    static void applyPatch(JSONObject w,JSONObject patch,JSONObject undo,JSONObject expected) throws Exception {JSONObject g=patch.optJSONObject("generation");if(g!=null)for(Iterator<String> it=g.keys();it.hasNext();){String k=it.next(),key=Set.of("difficulty","custom").contains(k)?"settings."+k:k;change(w,key,g.get(k),undo,expected);}if(patch.has("ui")){change(w,"settings.ui",patch.getJSONObject("ui"),undo,expected);change(w,"settings.theme",patch.getJSONObject("ui").getString("theme"),undo,expected);}}
    static void change(JSONObject w,String key,Object v,JSONObject undo,JSONObject expected) throws Exception {undo.put(key,value(w,key)==null?JSONObject.NULL:value(w,key));expected.put(key,v);set(w,key,v);}
}
